    public Object parseTickers(Object tickers, List<String> symbols, Map<String, Object> parameters)
    {
        Map<String, Object> result = new HashMap<String, Object>() {{}};
        List<Object> keys = Helpers.objectKeys(tickers);
        for (var i = 0; i < ((List<?>)keys).size(); i++)
        {
            Object key = (keys == null || i < 0 || i >= keys.size() ? null : keys.get(i));
            Object ticker = Helpers.GetValue(tickers, key);
            String marketId = this.safeString(ticker, "symbol", key);
            Map<String, Object> market = this.safeMarket(marketId, (Map<String, Object>) null, "-", (String) null);
            String symbol = (String) market.get("symbol");
            result.put((String)symbol, this.extend(this.parseTicker(ticker, market), parameters));
        }
        return this.filterByArrayTickers(result, "symbol", symbols, true);
    }

    public Object parseTicker(Object ticker, Map<String, Object> market)
    {
        //
        // fetchTicker
        //
        //     {
        //         "open": 8615.55,
        //         "close": 8841.05,
        //         "high": 8921.1,
        //         "low": 8607,
        //         "last": 8841.05,
        //         "volume": 20.2802,
        //         "timestamp": "2020-03-03T03:11:18.964Z",
        //     }
        //
        // fetchTickers
        //
        //     {
        //         "time": "2020-03-02T04:29:45.011Z",
        //         "open": 341.65,
        //         "close": 337.9,
        //         "high": 341.65,
        //         "low": 337.3,
        //         "last": 337.9,
        //         "volume": 0.054,
        //         "symbol": "bch-usdt"
        //     }
        //
        String marketId = this.safeString(ticker, "symbol");
        Map<String, Object> marketResolved = this.safeMarket(marketId, market, "-", (String) null);
        String symbol = (String) marketResolved.get("symbol");
        Long timestamp = this.parse8601(this.safeString2(ticker, "time", "timestamp"));
        String close = this.safeString(ticker, "close");
        return this.safeTicker(new HashMap<String, Object>() {{
            put( "symbol", symbol );
            put( "info", ticker );
            put( "timestamp", timestamp );
            put( "datetime", Hollaex.this.iso8601(timestamp) );
            put( "high", Hollaex.this.safeString(ticker, "high") );
            put( "low", Hollaex.this.safeString(ticker, "low") );
            put( "bid", null );
            put( "bidVolume", null );
            put( "ask", null );
            put( "askVolume", null );
            put( "vwap", null );
            put( "open", Hollaex.this.safeString(ticker, "open") );
            put( "close", close );
            put( "last", Hollaex.this.safeString(ticker, "last", close) );
            put( "previousClose", null );
            put( "change", null );
            put( "percentage", null );
            put( "average", null );
            put( "baseVolume", Hollaex.this.safeString(ticker, "volume") );
            put( "quoteVolume", null );
        }}, marketResolved);
    }

