    public Object parseDepositAddress(Map<String, Object> depositAddress, Map<String, Object> currency)
    {
        //
        //     {
        //         "currency":"usdt",
        //         "address":"TECLD9XBH31XpyykdHU3uEAeUK7E6Lrmik",
        //         "network":"trx",
        //         "standard":null,
        //         "is_valid":true,
        //         "created_at":"2021-05-12T02:43:05.446Z"
        //     }
        //
        String address = this.safeString(depositAddress, "address");
        String tag = null;
        if (!java.util.Objects.equals(address, null))
        {
            List<Object> parts = new ArrayList<Object>(Arrays.asList(((String)address).split(java.util.regex.Pattern.quote(":"))));
            address = this.safeString(parts, 0);
            tag = this.safeString(parts, 1);
        }
        this.checkAddress(address);
        String currencyId = this.safeString(depositAddress, "currency");
        Map<String, Object> currencyResolved = this.safeCurrency(currencyId, currency);
        String network = this.safeString(depositAddress, "network");
        return Helpers.newMap(
            "info", depositAddress,
            "currency", currencyResolved.get("code"),
            "network", network,
            "address", address,
            "tag", tag
        );
    }

